package org.firstinspires.ftc.teamcode;

import com.pedropathing.ivy.Command;
import static com.pedropathing.ivy.commands.Commands.*;
import static com.pedropathing.ivy.groups.Groups.sequential;
import com.qualcomm.robotcore.hardware.HardwareMap;
import com.qualcomm.robotcore.hardware.DcMotorEx;
import org.firstinspires.ftc.teamcode.pedro.Constants;

/**
 * Generated by the Pedro Pathing Visualizer for Send to robot.
 * Save it again and reinstall the app whenever you change robot actions;
 * PedroRoutineRun refuses routines whose actions do not match HASH.
 */
public class RobotActions {
    public static final String HASH = "862e56df";

    private DcMotorEx launch1, launch2, intake, ballmove;

    private final HardwareMap hardwareMap;

    public RobotActions(HardwareMap hardwareMap) {
        this.hardwareMap = hardwareMap;
        launch1 = hardwareMap.get(DcMotorEx.class, "launch");
        launch2 = hardwareMap.get(DcMotorEx.class, "launch2");
        intake = hardwareMap.get(DcMotorEx.class, "intake");
        ballmove = hardwareMap.get(DcMotorEx.class, "ballmove");
    }

    /** The command for an action's phase (start, stop or after), or null. */
    public Command command(String id, String phase) {
        switch (id + "/" + phase) {
            case "shoot/after":
                return sequential(
                    instant(() -> {
                        launch1.setVelocity(1600);
                        launch2.setVelocity(-1600);
                    }),
                    waitMs(1500),
                    instant(() -> {
                        intake.setPower(1);
                        ballmove.setPower(0.78);
                    }),
                    waitMs(2500),
                    instant(() -> {
                        launch1.setVelocity(0);
                        launch2.setVelocity(0);
                        intake.setPower(0);
                        ballmove.setPower(0);
                    })
                );
            case "intake/start":
                return instant(() -> {
                    intake.setPower(1);
                    ballmove.setPower(0.1);
                });
            case "intake/stop":
                return instant(() -> {
                    intake.setPower(0);
                    ballmove.setPower(0);
                });
            default:
                return null;
        }
    }
}
